function originalStats(buffer){let peak=0;const levels=[],channels=Array.from({length:buffer.numberOfChannels},(_,i)=>buffer.getChannelData(i));for(let start=0;start<buffer.length;start+=buffer.sampleRate){let energy=0,count=0;for(const c of channels)for(let i=start;i<Math.min(buffer.length,start+buffer.sampleRate);i++){const value=c[i];peak=Math.max(peak,Math.abs(value));energy+=value*value;count++;}levels.push(energy?10*Math.log10(energy/count):-Infinity);}return {peak:peak?20*Math.log10(peak):-Infinity,levels};}
function showLocal(buffer){const stats=originalStats(buffer);document.querySelector('#analysis').hidden=false;document.querySelector('#sample-peak').textContent=Number.isFinite(stats.peak)?stats.peak.toFixed(1):'−∞';document.querySelector('#chart-duration').textContent=`0:00 — ${clock(buffer.duration)}`;const points=stats.levels.map((v,i)=>`${40+i/Math.max(1,stats.levels.length-1)*850},${12+(1-(Math.max(-60,Math.min(0,v))+60)/60)*95}`).join(' ');document.querySelector('#level-chart').innerHTML=[0,-20,-40,-60].map(v=>{const y=12-v/60*95;return `<line x1="40" y1="${y}" x2="890" y2="${y}" stroke="#dce4df"/><text x="0" y="${y+4}" fill="#7b8986" font-size="10">${v}</text>`;}).join('')+`<polyline points="${points}" fill="none" stroke="#237b69" stroke-width="1.5"/>`;document.querySelector('#analysis-label').textContent='Original file · local sample measurements';}
window.addEventListener('recording-ready',e=>{analysisSerial++;analysisBusy=false;originalBuffer=e.detail.buffer;['#lufs','#true-peak','#lra'].forEach(id=>document.querySelector(id).textContent='—');showLocal(originalBuffer);document.querySelector('#analyze').disabled=false;document.querySelector('#analyze').textContent='Measure';});
async function analyzeRecording(){if(!selectedFile||analysisBusy)return;window.dispatchEvent(new CustomEvent('task-state',{detail:{task:'analysis',state:'running'}}));const measuredFile=selectedFile;const serial=++analysisSerial;analysisBusy=true;document.querySelector('#analyze').disabled=true;document.querySelector('#analyze').textContent='Measuring…';try{const form=new FormData();form.append('audio',selectedFile);const response=await fetch(API+'/analyze',{method:'POST',body:form,signal:AbortSignal.timeout(190000)});const data=await response.json();if(!response.ok)throw Error(data.error||'Measurement failed.');if(serial!==analysisSerial)return;for(const [id,key] of [['#lufs','integrated'],['#true-peak','true_peak'],['#lra','lra']])document.querySelector(id).textContent=data[key]===null?'Not measurable':Number(data[key]).toFixed(1);document.querySelector('#analysis-label').textContent='Original file · FFmpeg / EBU R128';drawLoudness(data,originalBuffer.duration);document.querySelector('#rms-panel').hidden=true;window.dispatchEvent(new CustomEvent('task-state',{detail:{task:'analysis',state:'complete'}}));window.dispatchEvent(new CustomEvent('analysis-ready',{detail:{data,file:measuredFile,buffer:originalBuffer}}));document.querySelector('#upload-state').textContent=busy?'Loudness measured. Separating instrument parts…':'Loudness measured.';}catch(e){if(serial===analysisSerial)window.dispatchEvent(new CustomEvent('task-state',{detail:{task:'analysis',state:'failed'}}));if(serial===analysisSerial)document.querySelector('#upload-state').textContent='Loudness measurement unavailable. Make sure the local service is running. '+(e.message||'');}finally{if(serial===analysisSerial){analysisBusy=false;document.querySelector('#analyze').disabled=false;document.querySelector('#analyze').textContent='Measure';}}}
document.querySelector('#analyze').onclick=analyzeRecording;
function saveAudio(blob,name){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
document.querySelector('#stems').addEventListener('click',e=>{const button=e.target.closest('[data-export]');if(!button)return;const i=Number(button.dataset.export),buffer=buffers[i];saveAudio(wav(Array.from({length:buffer.numberOfChannels},(_,c)=>buffer.getChannelData(c)),buffer.sampleRate),`unlayer-${tracks[i].name.toLowerCase()}.wav`);});

let originalBuffer=null,analysisSerial=0,analysisBusy=false;
function drawLoudness(data,total){const target=document.querySelector('#loudness-chart'),series=Array.isArray(data.short_term)?data.short_term.filter(p=>Number.isFinite(p.time)&&Number.isFinite(p.lufs)):[];document.querySelector('#loudness-timeline').hidden=false;if(!series.length){target.innerHTML='';document.querySelector('#timeline-note').textContent='No short-term samples available. A full 3-second window is required; older saved results may need reanalysis.';return;}const floor=-70,ceiling=0,left=44,right=885,top=12,bottom=157;const x=t=>left+t/Math.max(total,series.at(-1).time,1)*(right-left),y=v=>top+(ceiling-Math.max(floor,Math.min(ceiling,v)))/(ceiling-floor)*(bottom-top);let markup=[0,-20,-40,-60].map(v=>`<line x1="${left}" x2="${right}" y1="${y(v)}" y2="${y(v)}" stroke="#dce4df"/><text x="4" y="${y(v)+4}" fill="#7b8986" font-size="11">${v}</text>`).join('');markup+=`<polyline fill="none" stroke="#237b69" stroke-width="1.7" points="${series.map(p=>`${x(p.time)},${y(p.lufs)}`).join(' ')}"/>`;markup+=series.map(p=>`<circle cx="${x(p.time)}" cy="${y(p.lufs)}" r="5" fill="transparent"><title>${clock(p.time)} · ${p.lufs.toFixed(1)} LUFS</title></circle>`).join('');markup+=`<text x="${left}" y="184" fill="#7b8986" font-size="11">0:00</text><text x="${right}" y="184" text-anchor="end" fill="#7b8986" font-size="11">${clock(total||series.at(-1).time)}</text>`;target.innerHTML=markup;document.querySelector('#timeline-note').textContent='Three-second short-term loudness, sampled about once per second. Hover over points for values. Levels below −70 LUFS are drawn at the chart floor.';}
